import * as T from 'three';
const colors={wall:0xd6cdb5,white:0xe5e0d2,roof:0x424b47,wood:0x584336,red:0x933c2e,stone:0xb8b6a7,dark:0x253a35,gold:0xb18b43};
const matCache=new Map();function mat(c){if(!matCache.has(c))matCache.set(c,new T.MeshStandardMaterial({color:c,roughness:.92}));return matCache.get(c)}
function mesh(g,geo,c,x=0,y=0,z=0){let m=new T.Mesh(geo,typeof c==='number'?mat(c):c);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;g.add(m);return m}
function box(g,w,h,d,x,y,z,c=colors.wall){return mesh(g,new T.BoxGeometry(w,h,d),c,x,y,z)}
function pole(g,r,h,x,y,z,c=colors.wood){return mesh(g,new T.CylinderGeometry(r,r,h,8),c,x,y+h/2,z)}
function rod(g,a,b,r,c){let av=new T.Vector3(...a),bv=new T.Vector3(...b),delta=bv.clone().sub(av);let m=mesh(g,new T.CylinderGeometry(r,r,delta.length(),6),c);m.position.copy(av.add(bv).multiplyScalar(.5));m.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),delta.normalize());return m}
function plaque(g,text,w,x,y,z,bg='#293c35',fg='#d7c791'){let cv=document.createElement('canvas');cv.width=1024;cv.height=200;let c=cv.getContext('2d');c.fillStyle=bg;c.fillRect(0,0,1024,200);c.strokeStyle=fg;c.lineWidth=5;c.strokeRect(13,13,998,174);c.fillStyle=fg;c.textAlign='center';c.textBaseline='middle';c.font=`${Math.min(120,840/text.length)}px SimSun,serif`;c.fillText(text,512,105);let tx=new T.CanvasTexture(cv);tx.colorSpace=T.SRGBColorSpace;let material=new T.MeshStandardMaterial({map:tx,roughness:1});let m=mesh(g,new T.PlaneGeometry(w,w*200/1024),material,x,y,z);return m}
function roof(g,w,d,y,x=0,z=0,c=colors.roof,rise=2.4,hip=false){
 for(let side of [-1,1]){const pos=[],uv=[],idx=[];const nx=16,nz=10;for(let j=0;j<=nz;j++){let t=j/nz;for(let i=0;i<=nx;i++){let u=i/nx;let xx=(u-.5)*(hip?w*.70+w*.30*t:w);let yy=y+rise*Math.pow(1-t,.9)+.22*Math.pow(t,8);pos.push(x+xx,yy,z+side*t*d/2);uv.push(u,t)}}for(let j=0;j<nz;j++)for(let i=0;i<nx;i++){let a=j*(nx+1)+i;idx.push(a,a+1,a+nx+1,a+1,a+nx+2,a+nx+1)}let geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute(pos,3));geo.setAttribute('uv',new T.Float32BufferAttribute(uv,2));geo.setIndex(idx);geo.computeVertexNormals();mesh(g,geo,new T.MeshStandardMaterial({color:c,side:T.DoubleSide,roughness:1}));
 const num=Math.min(52,Math.round(w/.42));for(let i=0;i<=num;i++){let u=i/num;const points=[];for(let j=0;j<=10;j++){let t=j/10;points.push(new T.Vector3(x+(u-.5)*(hip?w*.7+w*.3*t:w),y+rise*Math.pow(1-t,.9)+.22*Math.pow(t,8)+.025,z+side*t*d/2))}mesh(g,new T.TubeGeometry(new T.CatmullRomCurve3(points),10,.025,3,false),c===colors.gold?0xc5a45c:0x626c63)}
 rod(g,[x-w/2,y+.24,z+side*d/2],[x+w/2,y+.24,z+side*d/2],.065,c);
 }rod(g,[x-w*(hip?.35:.5),y+rise+.08,z],[x+w*(hip?.35:.5),y+rise+.08,z],.12,c);
 if(hip){for(let s of [-1,1]){let geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute([x+s*w*.35,y+rise,z,x+s*w*.5,y+.22,z-d*.5,x+s*w*.5,y+.22,z+d*.5],3));geo.computeVertexNormals();mesh(g,geo,new T.MeshStandardMaterial({color:c,side:T.DoubleSide,roughness:1}))}}
}
function window(g,x,y,z,w=1.1,h=1.6,rot=0){const a=new T.Group();a.position.set(x,y,z);a.rotation.y=rot;g.add(a);box(a,w,h,.045,0,0,0,colors.dark);for(let sx of [-1,1])box(a,.08,h+.12,.12,sx*w/2,0,.025,colors.wood);for(let sy of [-1,1])box(a,w+.12,.08,.12,0,sy*h/2,.025,colors.wood);for(let k=1;k<4;k++)box(a,.035,h,.08,-w/2+k*w/4,0,.065,colors.wood);box(a,w,.045,.08,0,0,.065,colors.wood)}
function door(g,x,y,z,w=1.3,h=2.4){box(g,w,h,.10,x,y+h/2,z,colors.wood);for(let i=0;i<6;i++)box(g,.018,h,.12,x-w/2+(i+.5)*w/6,y+h/2,z+.03,0x80654a);for(let s of [-1,1]){box(g,.12,h+.15,.22,x+s*(w/2+.09),y+h/2,z,colors.stone);mesh(g,new T.TorusGeometry(.045,.013,5,10),colors.gold,x+s*.14,y+h*.43,z+.1)}box(g,w+.35,.14,.23,x,y+h+.08,z,colors.stone)}
function house(g,{w=12,d=6,h=3.3,x=0,z=0,y=0,stories=1,wall=colors.wall,tile=colors.roof,sign='',hip=false,porch=false,roofExtra=1.5,roofCenter=0}={}){let a=new T.Group();a.position.set(x,y,z);g.add(a);box(a,w+.3,.28,d+.3,0,.14,0,colors.stone);box(a,w,h*stories,d,0,.28+h*stories/2,0,wall);for(let st=0;st<stories;st++){let n=Math.max(3,Math.floor(w/2.4));for(let i=0;i<n;i++){let xx=(i-(n-1)/2)*w/n;if(st===0&&i===Math.floor(n/2))door(a,xx,.28,d/2+.065);else window(a,xx,.28+h*st+h*.51,d/2+.06,1.1,1.5);window(a,xx,.28+h*st+h*.51,-d/2-.06,1.1,1.4,Math.PI)}for(let side of [-1,1])for(let j of [-1,1])window(a,side*(w/2+.035),.28+st*h+h*.51,j*d*.25,1,1.4,side*Math.PI/2);if(st>0)box(a,w+.1,.15,d+.1,0,.28+st*h,0,colors.wood)}if(!hip){for(let side of [-1,1]){const geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute([side*w/2,h*stories+.28,-d/2,side*w/2,h*stories+2.3,0,side*w/2,h*stories+.28,d/2],3));geo.computeVertexNormals();mesh(a,geo,new T.MeshStandardMaterial({color:wall,side:T.DoubleSide,roughness:1}))}}roof(a,w+(porch?3:1.3),d+(porch?3.5:roofExtra),h*stories+.3,0,porch?.5:roofCenter,tile,2,hip);if(sign)plaque(a,sign,Math.min(w*.52,6),0,h*stories-.25,d/2+.17);if(porch){box(a,w+1,.18,1.9,0,.25,d/2+.9,colors.stone);for(let i=0;i<=6;i++)pole(a,.10,h*stories,(i-3)*w/6,.32,d/2+1.1);box(a,w+1,.22,.3,0,h*stories+.2,d/2+1.1,colors.wood)}return a}
function stair(g,w,n,x,z,y=0){for(let i=0;i<n;i++)box(g,w,.18*(i+1),.45,x,y+.09*(i+1),z-.42*i,colors.stone)}
function tree(g,x,z,scale=1){let a=new T.Group();a.position.set(x,0,z);a.scale.setScalar(scale);g.add(a);pole(a,.13,2.5,0,0,0,0x655d48);for(let i=0;i<3;i++){let m=mesh(a,new T.IcosahedronGeometry(1.25-i*.15,1),0x586b51,Math.sin(i*3)*.4,2.7+i*.55,Math.cos(i*3)*.3);m.scale.y=.65}return a}
function wall(g,w,x,z){box(g,w,1.9,.3,x,.95,z,colors.wall);roof(g,w+.2,.6,1.9,x,z,colors.roof,.28)}
function ground(g,w=30,d=25){box(g,w,.35,d,0,-.27,0,0xc4c7b4);box(g,w+.2,.12,d+.2,0,-.49,0,0x9ca894);for(let i=-4;i<=4;i++){box(g,.025,.006,d, i*w/9,-.086,0,0xb7bfad)}for(let i=-3;i<=3;i++)box(g,w,.006,.025,0,-.083,i*d/7,0xb7bfad)}
function courtyard(g,{w=15,d=6,back=-6,front=7,sign='',color=colors.wall,tile=colors.roof}={}){house(g,{w,d,h:3.6,z:back,wall:color,tile,sign,porch:true});for(let s of [-1,1]){let a=house(g,{w:front-back+4,d:3.7,h:2.8,x:s*(w/2+1.8),z:(front+back)/2,wall:color,tile});a.rotation.y=Math.PI/2}house(g,{w:w+3.8,d:3.3,h:2.9,z:front,wall:color,tile,sign:sign==='古田会议会址'?'古田会议会址':''});stair(g,4,3,0,front+3.2)}
function archShape(w,h,bottom=0,x=0){const p=new T.Path();p.moveTo(x-w/2,bottom);p.lineTo(x-w/2,h-w/2);p.absarc(x,h-w/2,w/2,Math.PI,0,true);p.lineTo(x+w/2,bottom);p.closePath();return p}
function arch(g,x,y,z,w,h,c=colors.dark){let s=new T.Shape();s.moveTo(-w/2,0);s.lineTo(-w/2,h-w/2);s.absarc(0,h-w/2,w/2,Math.PI,0,true);s.lineTo(w/2,0);s.closePath();mesh(g,new T.ShapeGeometry(s),c,x,y,z);for(let i=0;i<=12;i++){let ang=i*Math.PI/12;let b=box(g,.19,.28,.2,x+Math.cos(ang)*(w/2+.14),y+h-w/2+Math.sin(ang)*(w/2+.14),z+.08,colors.stone);b.rotation.z=ang-Math.PI/2}box(g,.2,h-w/2,.2,x-w/2-.13,y+(h-w/2)/2,z+.08,colors.stone);box(g,.2,h-w/2,.2,x+w/2+.13,y+(h-w/2)/2,z+.08,colors.stone)}
export function createModel(type){const g=new T.Group();ground(g,type==='gate'?49:type==='school'?34:32,type==='school'?40:type==='gate'?34:28);
 switch(type){
 case 'shaoshan':{house(g,{w:19,d:5,h:3.2,z:-4,wall:0xc4b38e});house(g,{w:5,d:10,h:3.2,x:-7,z:2,wall:0xbba886});house(g,{w:5,d:9,h:3.2,x:7,z:1.5,wall:0xd9cbb0});box(g,10,.018,5,0,-.045,9,0x79978a);tree(g,-13,-8,1.6);tree(g,13,-8,1.3);break}
 case 'academy':{house(g,{w:17,d:9,h:4,z:-2,wall:colors.white,sign:'实事求是',porch:true,hip:true});for(let s of [-1,1]){let h=house(g,{w:14,d:3,h:3,x:s*11,z:2,wall:colors.white});h.rotation.y=Math.PI/2;tree(g,s*7,8,1.1)}stair(g,11,3,0,4.5);break}
 case 'school':{house(g,{w:17,d:8,h:4.6,z:-10,wall:colors.red,tile:colors.gold,sign:'大成殿',porch:true,hip:true});house(g,{w:12,d:4,h:3.5,z:3,wall:colors.red,tile:colors.gold,sign:'农民运动讲习所'});for(let s of [-1,1]){let a=house(g,{w:22,d:3,h:2.7,x:s*12,z:-2,wall:colors.red,tile:colors.gold});a.rotation.y=Math.PI/2}for(let x of [-4,0,4]){pole(g,.24,5,x,0,14,colors.stone);box(g,4.4,.25,.4,x,4.2,14,colors.stone)}box(g,9,.45,.6,0,4.8,14,colors.stone);plaque(g,'农民运动讲习所',7,0,4.8,14.32);break}
 case 'bajiaolou':{house(g,{w:10,d:7,h:3,z:-2,stories:2,wall:0xcbbb9a,sign:'八角楼'});house(g,{w:4,d:6,h:3,x:-7,z:-1,wall:0xb5a27e});house(g,{w:4,d:6,h:3,x:7,z:-1,wall:0xb5a27e});wall(g,16,0,9);tree(g,-12,-7,1.8);tree(g,12,7,1.3);stair(g,4,3,0,2.6);break}
 case 'gutian':{courtyard(g,{w:17,sign:'古田会议会址',color:0xe2dfd1});tree(g,-14,-8,1.3);tree(g,14,-9,1.1);break}
 case 'xunwu':{let h=house(g,{w:19,d:8,h:3.3,z:-2,stories:2,wall:0xb9a083,hip:true,roofExtra:4.6,roofCenter:.8});box(h,20,.19,2.4,0,3.58,5,colors.stone);for(let i=0;i<=8;i++){let x=(i-4)*2.3;pole(h,.10,6.6,x,.25,6,colors.red)}for(let side of [-1,1]){box(h,7.5,.12,.14,side*6.2,4.6,6,colors.red);for(let i=0;i<15;i++)box(h,.06,.95,.08,side*(2.6+i*.5),4.1,6,colors.red)}door(h,0,3.68,4.1,2.2,2.5);plaque(h,'毛泽东同志旧居',5,0,6.3,6.05,'#933c2e');for(let i=0;i<19;i++){let y=(i+1)*3.58/19,z=11.6-i*.4;box(g,4.6,y,.44,0,y/2,z,colors.stone)}for(let side of [-1,1]){rod(g,[side*2.4,1,11.8],[side*2.4,4.6,4.2],.1,colors.stone);for(let i=0;i<=9;i++)pole(g,.10,.9,side*2.4,i*.38,11.6-i*.8,colors.stone)}tree(g,-11,8,.85);tree(g,11,8,.85);break}
 case 'caixi':{courtyard(g,{w:13,back:-5,front:6,sign:'列宁堂',color:0xc9b68d});tree(g,-13,-8,1.3);break}
 case 'zunyi':{house(g,{w:17,d:9,h:3.2,stories:2,z:-2,wall:0xc0c3b6,porch:true,hip:true,sign:'遵义会议会址'});for(let side of [-1,1]){for(let i=0;i<=5;i++)pole(g,.12,6.6,side*9.5,.2,-6+i*2);box(g,1.8,.18,12,side*9.2,3.5,-1);box(g,.1,.1,12,side*9.6,4.5,-1,colors.wood);for(let i=0;i<22;i++)box(g,.07,.9,.055,side*9.6,4,-6.5+i*.5,colors.wood)}box(g,20,.15,1.8,0,3.5,3.7,colors.stone);box(g,20,.1,.12,0,4.5,4.5,colors.wood);for(let i=0;i<42;i++)box(g,.045,.9,.075,(i-20.5)*.47,4,4.5,colors.wood);tree(g,-13,8,1.5);break}
 case 'cave':{box(g,21,5.2,9,0,2.6,-5,0xb9ad8f);for(let x of [-6,0,6]){arch(g,x,.1,-.43,3.5,4.2);door(g,x,.15,-.32,1.25,2.7);for(let xx of [-1,1])window(g,x+xx*1.15,1.7,-.29,.65,2.2)}box(g,22,.27,9.5,0,5.3,-5,0xc5b895);let a=house(g,{w:12,d:4,h:3,x:12,z:2,wall:colors.wall});a.rotation.y=Math.PI/2;tree(g,-12,5,1.3);wall(g,15,0,10);break}
 case 'hall':{box(g,18,5.5,21,0,2.75,-2,0xb9aa8c);box(g,18.5,.25,21.5,0,5.6,-2,colors.stone);box(g,11,2.2,18,0,6.8,-3,0xc8b99b);box(g,11.5,.22,18.5,0,7.95,-3,colors.stone);for(let side of [-1,1]){for(let i=0;i<7;i++){window(g,side*9.04,2.8,-10+i*2.7,1.4,3.4,side*Math.PI/2);window(g,side*5.55,6.8,-10+i*2.4,1.2,1.25,side*Math.PI/2)}}box(g,8.7,10.6,4.6,0,5.3,7,0xc3b28f);for(let x of [-4.3,4.3])box(g,.65,10.8,5,x,5.4,7,0xe0d4b9);box(g,9.5,.3,5.3,0,10.9,7,colors.stone);for(let i=0;i<13;i++)box(g,.15,.65,.2,(i-6)*.65,10.4,9.5,colors.white);door(g,0,.45,9.36,2.2,3.4);for(let x of [-2.7,2.7])window(g,x,2.4,9.36,1.7,3.5);box(g,8.2,.4,.4,0,4.55,9.5,0x506451);plaque(g,'中央大礼堂',6,0,5.35,9.38,'#c3b28f','#625036');mesh(g,new T.CircleGeometry(1.25,32),colors.dark,0,7.7,9.4);mesh(g,new T.TorusGeometry(1.3,.12,8,32),colors.stone,0,7.7,9.43);for(let i=0;i<12;i++){let a=i*Math.PI/6;rod(g,[0,7.7,9.46],[Math.cos(a)*1.2,7.7+Math.sin(a)*1.2,9.46],.035,colors.white)}pole(g,.05,4,0,10.9,7,colors.wood);mesh(g,new T.PlaneGeometry(2.4,1.4),new T.MeshStandardMaterial({color:colors.red,side:T.DoubleSide}),1.2,14,7);stair(g,9,4,0,11.4);break}
 case 'xibaipo':{house(g,{w:23,d:7,h:3.3,z:-3,wall:0xc0b498,sign:'中国共产党七届二中全会会址'});tree(g,-13,5,1.6);tree(g,13,5,1.5);stair(g,6,2,0,2);break}
 case 'gate':{let sh=new T.Shape();sh.moveTo(-19,0);sh.lineTo(19,0);sh.lineTo(19,7);sh.lineTo(-19,7);sh.closePath();for(let x of [-13,-6.5,0,6.5,13]){let w=x===0?3.5:2.6,h=x===0?5:4;sh.holes.push(archShape(w,h,.025,x))}mesh(g,new T.ExtrudeGeometry(sh,{depth:12,bevelEnabled:false}),colors.red,0,0,-6);box(g,39,.35,13,0,7.15,0,colors.stone);house(g,{w:30,d:9,h:4.3,y:7.5,wall:colors.red,tile:colors.gold,hip:true,porch:true});roof(g,34,13,10,0,0,colors.gold,2,true);for(let z of [-6.3,6.3]){box(g,39,.13,.18,0,8.4,z,colors.white);for(let i=0;i<=40;i++)pole(g,.075,1.05,(i-20)*.95,7.35,z,colors.white)}for(let s of [-1,1])for(let i=0;i<3;i++){let x=s*(7+i*4);pole(g,.05,3,x,7.6,6,colors.wood);let flag=mesh(g,new T.PlaneGeometry(1.6,.9,8,4),new T.MeshStandardMaterial({color:0xb63e31,side:T.DoubleSide,roughness:1}),x+.8,10.2,6);let p=flag.geometry.attributes.position;for(let j=0;j<p.count;j++)p.setZ(j,Math.sin(p.getX(j)*3)*.1);p.needsUpdate=true}for(let x of [-10,-5,0,5,10]){box(g,2.7,.18,8,x,.1,11,colors.stone);for(let s of [-1,1]){box(g,.1,.1,8,x+s*1.3,1.1,11,colors.white);for(let j=0;j<9;j++)pole(g,.06,1,x+s*1.3,.1,7+j,colors.white)}}break}
 }
 g.userData.kind=type;return g;
}
export function disposeModel(g){const materials=new Set(),geometries=new Set();g.traverse(o=>{if(o.geometry)geometries.add(o.geometry);if(o.material){for(let m of (Array.isArray(o.material)?o.material:[o.material])){if(m.map){m.map.dispose();materials.add(m)}else if(![...matCache.values()].includes(m))materials.add(m)}}});geometries.forEach(x=>x.dispose());materials.forEach(x=>x.dispose())}
